def contains_subsequence(arr, seq):
    seq_len = len(seq)
    # Empty sequence
    if seq_len == 0:
        return True
    i = 0
    for item in arr:
        if item == seq[i]:
            i += 1
            if i == seq_len:
                break
    return i == seq_len

